from typing import List, Optional
from wordle.types import GuessResult, GameStatus, InvalidGuessError, GameOverError
from unittest.mock import MagicMock

class Game:
    def __init__(self, target: Optional[str] = None):
        self.target = target if target else self.get_random_word()
        self.attempts = 6
        self.status = GameStatus.IN_PROGRESS
        self.results = []
        self.words = self.load_dictionary()

    def make_guess(self, guess: str) -> GuessResult:
        if self.status != GameStatus.IN_PROGRESS:
            raise GameOverError("Game is over")

        guess = self._validate_guess(guess)

        feedbacks = self.score_guess(guess, self.target)

        result = GuessResult(guess, feedbacks)

        self.results.append(result)

        if guess == self.target:
            self.status = GameStatus.WON
        else:
            self.attempts -= 1
            if self.attempts == 0:
                self.status = GameStatus.LOST

        return result

    def get_status(self) -> GameStatus:
        return self.status

    def get_results(self) -> List[GuessResult]:
        return self.results

    def get_attempts_remaining(self) -> int:
        return self.attempts

    def get_target_word(self) -> Optional[str]:
        if self.status != GameStatus.IN_PROGRESS:
            return self.target
        return None

    def reset(self, target: Optional[str] = None) -> None:
        self.__init__(target)

    def _validate_guess(self, guess: str) -> str:
        if len(guess) != 5:
            raise InvalidGuessError("Guess must be 5 letters long")
        if guess not in self.words:
            raise InvalidGuessError("Guess is not a valid word")
        return guess

    @staticmethod
    def score_guess(guess: str, target: str) -> List[Feedback]:
        feedbacks = []
        for i in range(5):
            if guess[i] == target[i]:
                feedbacks.append(Feedback.HIT)
            elif guess[i] in target:
                feedbacks.append(Feedback.PRESENT)
            else:
                feedbacks.append(Feedback.MISS)
        return feedbacks

    @staticmethod
    def load_dictionary() -> Set[str]:
        # Mock loading a dictionary of 5-letter words
        return {"HELLO", "WORLD", "HOUSE", "TREEs"}

    @staticmethod
    def get_random_word() -> str:
        # Mock getting a random word from the dictionary
        return "WORLD"

